package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;import java.net.*;import java.util.*;
/** Cancellation is a local stop request. Delivery already attempted is never claimed undone. */
final class CancellableWork {
 static final Map<String,Task> active=new HashMap<>();static final ThreadLocal<Task> current=new ThreadLocal<>();
 static final class Task {final Context context;final String key;final JSONObject record;volatile boolean stop,timedOut;final long startedElapsed=android.os.SystemClock.elapsedRealtime();final Set<HttpURLConnection> connections=new HashSet<>();Task(Context c,String k,JSONObject r){context=c;key=k;record=r;}}
 static final java.util.concurrent.ScheduledExecutorService deadlines=java.util.concurrent.Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"LokiWorkDeadline");t.setDaemon(true);return t;});
 static {deadlines.scheduleWithFixedDelay(()->{try{expireAt(android.os.SystemClock.elapsedRealtime());}catch(Exception ignored){}},15,15,java.util.concurrent.TimeUnit.SECONDS);}
 static long limit(String kind){return kind.equals("image")?900000L:kind.equals("import")?600000L:2700000L;}
 static synchronized void expireAt(long now){for(Task t:active.values()){if(t.stop||now<t.startedElapsed||now-t.startedElapsed<limit(t.record.optString("kind")))continue;t.stop=true;t.timedOut=true;try{t.record.put("phase",t.record.optInt("sentRequests")>0?"RESULT_UNKNOWN":"TIMED_OUT").put("stopAt",System.currentTimeMillis());persist(t);StabilityJournal.note(t.context,t.record.optString("usageRun"),t.record.optString("kind").toUpperCase(java.util.Locale.ROOT),"TIMEOUT","DEADLINE",now-t.startedElapsed);}catch(Exception ignored){}for(HttpURLConnection connection:t.connections)connection.disconnect();}}
 static String phaseLabel(String phase){switch(phase){case "TIMED_OUT":return "待機上限に達しました";case "RESULT_UNKNOWN":return "送信済み・結果未確認。自動再送しません";case "COMPLETED_AFTER_TIMEOUT":return "時間上限後に完了の記録あり";case "UNCONFIRMED_AFTER_RESTART":return "再起動後・結果未確認";default:return phase;}}
 static String key(String kind,String id)throws Exception{if(!kind.matches("meeting|image|video|import")||!id.matches("(?:[0-9]{13}-)?[a-f0-9-]{36}"))throw new IOException("処理IDが不正です");return kind+":"+id;}
 static synchronized void persist(Task t)throws Exception{JSONObject store=ReviewStore.read(t.context,"jobs");JSONArray all=store.optJSONArray("items"),out=new JSONArray();if(all!=null)for(int i=0;i<all.length();i++)if(!all.getJSONObject(i).getString("key").equals(t.key))out.put(all.get(i));if(out.length()>=50){JSONArray compact=new JSONArray();boolean removed=false;for(int i=0;i<out.length();i++){JSONObject row=out.getJSONObject(i);if(!removed&&row.optLong("endedAt")>0){removed=true;continue;}compact.put(row);}if(!removed)throw new IOException("未確定の処理記録が50件です。古い中止要求を消さずに停止しました");out=compact;}out.put(new JSONObject(t.record.toString()));ReviewStore.write(t.context,"jobs",new JSONObject().put("items",out));}
 static synchronized Task reserve(Context c,String kind,String id)throws Exception{String key=key(kind,id);if(active.containsKey(key))throw new IOException("同じ処理の終了を待ってください");Task t=new Task(c.getApplicationContext(),key,new JSONObject().put("key",key).put("kind",kind).put("id",id).put("usageRun",UUID.randomUUID().toString()).put("at",System.currentTimeMillis()).put("phase","QUEUED").put("sentRequests",0).put("sentBytes",0));persist(t);active.put(key,t);StabilityJournal.note(c,t.record.optString("usageRun"),kind.toUpperCase(java.util.Locale.ROOT),"START","NONE",0);return t;}
 static void enter(Context c,String kind,String id)throws Exception{Task t;synchronized(CancellableWork.class){t=active.get(key(kind,id));if(t==null){if(wasStopped(c,kind,id))throw new InterruptedIOException("以前の中止要求を保持しています。必要な場合だけ新しく確認して開始してください");t=reserve(c,kind,id);}current.set(t);if(!t.stop){t.record.put("phase","RUNNING");persist(t);}}check();}
 static void check()throws IOException{expireAt(android.os.SystemClock.elapsedRealtime());Task t=current.get();if(Thread.currentThread().isInterrupted()||t!=null&&t.stop)throw new InterruptedIOException("中止要求で停止しました。送信済みの処理・料金は取り消せません。保存済み区間は保持しています");}
 static synchronized void bind(HttpURLConnection connection)throws Exception{check();Task t=current.get();if(t!=null)t.connections.add(connection);}
 static HttpURLConnection connection(URL url,long bytes)throws Exception{Task t=current.get();if(t==null){if(TransferNetwork.bulk(bytes,false))throw new IOException("大きな送信の通信設定を確認できません");return (HttpURLConnection)url.openConnection();}return TransferNetwork.open(t.context,url,bytes,t.record.optString("kind").equals("video"));}
 static synchronized void sending(long bytes)throws Exception{check();Task t=current.get();if(t!=null){TransferNetwork.require(t.context,bytes,t.record.optString("kind").matches("video|image"));t.record.put("lastInputBytes",Math.max(0,bytes)).put("sentRequests",t.record.optInt("sentRequests")+1).put("sentBytes",t.record.optLong("sentBytes")+Math.max(0,bytes)).put("phase","DELIVERY_ATTEMPTED");persist(t);try{UsageLedger.recordRun(t.context,t.record.getString("id"),t.record.getString("kind"),t.record.getString("usageRun"),t.record.getInt("sentRequests"),Math.max(0,bytes),null);}catch(Exception ignored){}}}
 static synchronized JSONObject cancel(Context c,String kind,String id)throws Exception{String key=key(kind,id);Task t=active.get(key);if(t==null)throw new IOException("この起動中に動いている処理はありません。完了・再起動後の記録を確認してください");t.stop=true;t.record.put("phase","STOP_REQUESTED").put("stopAt",System.currentTimeMillis());Exception failure=null;try{persist(t);}catch(Exception e){failure=e;}for(HttpURLConnection connection:t.connections)connection.disconnect();if(failure!=null)throw new IOException("停止を要求しましたが記録を保存できません。結果を確認してください");return new JSONObject(t.record.toString()).put("message","中止を要求しました。すでに送信した内容や生成料金は取り消せません。完了済みの保存物は保持します");}
 static synchronized void finish(boolean success){Task t=current.get();try{if(t!=null){t.record.put("phase",t.timedOut?(success?"COMPLETED_AFTER_TIMEOUT":t.record.optInt("sentRequests")>0?"RESULT_UNKNOWN":"TIMED_OUT"):success?(t.stop?"COMPLETED_AFTER_STOP":"COMPLETED"):(t.stop?"STOPPED":"FAILED")).put("endedAt",System.currentTimeMillis());persist(t);StabilityJournal.note(t.context,t.record.optString("usageRun"),t.record.optString("kind").toUpperCase(java.util.Locale.ROOT),t.timedOut?(success?"END":"RESULT_UNKNOWN"):success?"END":"ERROR",t.timedOut?"DEADLINE":"NONE",android.os.SystemClock.elapsedRealtime()-t.startedElapsed);active.remove(t.key);}}catch(Exception ignored){}finally{if(t!=null)active.remove(t.key);current.remove();}}
 static synchronized boolean wasStopped(Context c,String kind,String id)throws Exception{String key=key(kind,id);JSONArray rows=ReviewStore.read(c,"jobs").optJSONArray("items");for(int i=rows==null?-1:rows.length()-1;i>=0;i--){JSONObject row=rows.getJSONObject(i);if(key.equals(row.optString("key")))return row.optLong("stopAt")>0;}return false;}
 static synchronized void abandon(Context c,String kind,String id){try{Task t=active.get(key(kind,id));if(t!=null){t.stop=true;t.record.put("phase","START_UNCONFIRMED").put("stopAt",System.currentTimeMillis()).put("endedAt",System.currentTimeMillis());try{persist(t);}finally{active.remove(t.key);}}}catch(Exception ignored){}}
 static void detach(){current.remove();}
 static synchronized JSONArray list(Context c)throws Exception{JSONArray rows=ReviewStore.read(c,"jobs").optJSONArray("items"),out=new JSONArray();if(rows!=null)for(int i=rows.length()-1;i>=0;i--){JSONObject row=new JSONObject(rows.getJSONObject(i).toString());boolean running=active.containsKey(row.optString("key"));row.put("canStop",running&&!row.optString("phase").matches("TIMED_OUT|RESULT_UNKNOWN"));row.put("phaseLabel",phaseLabel(row.optString("phase")));if(!running&&row.optLong("endedAt")==0)row.put("phase","UNCONFIRMED_AFTER_RESTART");out.put(row);}return out;}
 private CancellableWork(){}
}
